#!/usr/bin/env python3
"""Update the Gateway API Standard CRDs chart from an upstream release."""

from __future__ import annotations

import argparse
import copy
import os
from pathlib import Path
import re
import shutil
import sys
import tempfile
from typing import Any
from urllib.error import HTTPError, URLError
from urllib.request import urlopen

import yaml


CHART = Path(__file__).resolve().parents[1] / "charts/gateway-api-standard-crds"
GENERATED_HEADER = (
    "# Copyright The Kubernetes Authors.\n"
    "# SPDX-License-Identifier: Apache-2.0\n"
    "# Generated by scripts/update-gateway-api-standard-crds.py; do not edit.\n"
)
SEMVER = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)"
    r"(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)
ALLOWED_KINDS = {
    "CustomResourceDefinition",
    "ValidatingAdmissionPolicy",
    "ValidatingAdmissionPolicyBinding",
}
HELM_LABELS = {
    "app.kubernetes.io/name": "{{ .Chart.Name }}",
    "helm.sh/chart": "{{ .Chart.Name }}-{{ .Chart.Version }}",
    "app.kubernetes.io/managed-by": "{{ .Release.Service }}",
    "app.kubernetes.io/version": "{{ .Chart.AppVersion }}",
}


class UpdateError(Exception):
    """Expected update failure."""


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--gateway-version", required=True)
    parser.add_argument("--chart-version", required=True)
    return parser.parse_args()


def normalize_version(value: str, option: str, allow_v: bool = False) -> str:
    normalized = value[1:] if allow_v and value.startswith("v") else value
    if not SEMVER.fullmatch(normalized):
        raise UpdateError(f"{option} must be a valid SemVer: {value!r}")
    return normalized


def download_bundle(version: str) -> bytes:
    url = (
        "https://github.com/kubernetes-sigs/gateway-api/releases/download/"
        f"v{version}/standard-install.yaml"
    )
    try:
        with urlopen(url, timeout=60) as response:
            return response.read()
    except (HTTPError, URLError, TimeoutError) as error:
        raise UpdateError(f"failed to download {url}: {error}") from error


def parse_bundle(content: bytes, version: str) -> list[dict[str, Any]]:
    try:
        documents = list(yaml.safe_load_all(content))
    except yaml.YAMLError as error:
        raise UpdateError(f"upstream bundle is invalid YAML: {error}") from error

    if not documents:
        raise UpdateError("upstream bundle contains no documents")

    resources: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    kind_counts: dict[str, int] = {}
    expected_bundle_version = f"v{version}"

    for index, document in enumerate(documents, start=1):
        if document is None:
            raise UpdateError(f"upstream bundle contains empty document {index}")
        if not isinstance(document, dict):
            raise UpdateError(f"upstream document {index} is not a YAML mapping")

        api_version = document.get("apiVersion")
        kind = document.get("kind")
        metadata = document.get("metadata")
        if not isinstance(api_version, str) or not isinstance(kind, str):
            raise UpdateError(f"upstream document {index} lacks apiVersion or kind")
        if kind not in ALLOWED_KINDS:
            raise UpdateError(f"unexpected resource kind in Standard bundle: {kind}")
        if not isinstance(metadata, dict) or not isinstance(metadata.get("name"), str):
            raise UpdateError(f"upstream document {index} lacks metadata.name")

        name = metadata["name"]
        key = (kind, name)
        if key in seen:
            raise UpdateError(f"duplicate upstream resource: {kind}/{name}")
        seen.add(key)

        annotations = metadata.get("annotations")
        if not isinstance(annotations, dict):
            raise UpdateError(f"{kind}/{name} lacks upstream annotations")
        if annotations.get("gateway.networking.k8s.io/channel") != "standard":
            raise UpdateError(f"{kind}/{name} is not from the Standard channel")
        if annotations.get("gateway.networking.k8s.io/bundle-version") != expected_bundle_version:
            raise UpdateError(
                f"{kind}/{name} bundle version does not match v{version}"
            )

        if kind == "CustomResourceDefinition":
            spec = document.get("spec")
            if not isinstance(spec, dict) or spec.get("group") != "gateway.networking.k8s.io":
                raise UpdateError(f"unexpected CRD group for {name}")
        elif name != "safe-upgrades.gateway.networking.k8s.io":
            raise UpdateError(f"unexpected admission resource: {kind}/{name}")

        kind_counts[kind] = kind_counts.get(kind, 0) + 1
        resources.append(document)

    if kind_counts.get("CustomResourceDefinition") != 10:
        raise UpdateError("Standard bundle must contain exactly 10 CRDs")
    for kind in ("ValidatingAdmissionPolicy", "ValidatingAdmissionPolicyBinding"):
        if kind_counts.get(kind) != 1:
            raise UpdateError(f"Standard bundle must contain exactly one {kind}")

    return resources


def add_helm_metadata(resource: dict[str, Any]) -> dict[str, Any]:
    rendered = copy.deepcopy(resource)
    metadata = rendered["metadata"]
    labels = metadata.setdefault("labels", {})
    if not isinstance(labels, dict):
        raise UpdateError(f"metadata.labels is not a mapping for {metadata['name']}")
    labels.update(HELM_LABELS)

    if rendered["kind"] == "CustomResourceDefinition":
        annotations = metadata.setdefault("annotations", {})
        if not isinstance(annotations, dict):
            raise UpdateError(
                f"metadata.annotations is not a mapping for {metadata['name']}"
            )
        annotations["helm.sh/resource-policy"] = "keep"
    return rendered


def resource_filename(resource: dict[str, Any]) -> str:
    return f"{resource['kind'].lower()}-{resource['metadata']['name']}.yaml"


def write_generated(directory: Path, resources: list[dict[str, Any]]) -> None:
    directory.mkdir()
    expected_files: set[str] = set()
    for resource in sorted(resources, key=lambda item: resource_filename(item)):
        filename = resource_filename(resource)
        if filename in expected_files:
            raise UpdateError(f"duplicate generated filename: {filename}")
        expected_files.add(filename)
        body = yaml.safe_dump(
            add_helm_metadata(resource),
            sort_keys=False,
            default_flow_style=False,
            allow_unicode=True,
            width=4096,
        )
        (directory / filename).write_text(GENERATED_HEADER + body, encoding="utf-8")

    actual_files = {path.name for path in directory.iterdir() if path.is_file()}
    if actual_files != expected_files or len(actual_files) != len(resources):
        raise UpdateError("generated output is incomplete")

    reparsed = []
    for path in sorted(directory.iterdir()):
        with path.open(encoding="utf-8") as stream:
            documents = list(yaml.safe_load_all(stream))
        if len(documents) != 1 or not isinstance(documents[0], dict):
            raise UpdateError(f"generated file is invalid: {path.name}")
        reparsed.append(documents[0])
    if len({(item["kind"], item["metadata"]["name"]) for item in reparsed}) != len(resources):
        raise UpdateError("generated output contains duplicate resources")


def update_chart_text(chart_text: str, gateway_version: str, chart_version: str) -> str:
    def replace_field(text: str, field: str, value: str) -> str:
        pattern = re.compile(rf"(?m)^{re.escape(field)}:.*$")
        if len(pattern.findall(text)) != 1:
            raise UpdateError(f"Chart.yaml must contain exactly one {field} field")
        return pattern.sub(f'{field}: "{value}"', text)

    chart_text = replace_field(chart_text, "version", chart_version)
    return replace_field(chart_text, "appVersion", gateway_version)


def install_update(staged_generated: Path, staged_chart: Path) -> None:
    generated = CHART / "templates/generated"
    chart_file = CHART / "Chart.yaml"
    backup_generated = staged_generated.parent / "generated.backup"
    backup_chart = staged_generated.parent / "Chart.yaml.backup"
    had_generated = generated.exists()

    generated.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(chart_file, backup_chart)
    if had_generated:
        os.replace(generated, backup_generated)
    try:
        os.replace(staged_generated, generated)
        os.replace(staged_chart, chart_file)
    except OSError:
        if generated.exists():
            shutil.rmtree(generated)
        if had_generated and backup_generated.exists():
            os.replace(backup_generated, generated)
        os.replace(backup_chart, chart_file)
        raise
    if backup_generated.exists():
        shutil.rmtree(backup_generated)


def main() -> int:
    try:
        args = parse_args()
        gateway_version = normalize_version(
            args.gateway_version, "--gateway-version", allow_v=True
        )
        chart_version = normalize_version(args.chart_version, "--chart-version")
        resources = parse_bundle(download_bundle(gateway_version), gateway_version)
        chart_file = CHART / "Chart.yaml"
        chart_text = update_chart_text(
            chart_file.read_text(encoding="utf-8"), gateway_version, chart_version
        )

        CHART.mkdir(parents=True, exist_ok=True)
        with tempfile.TemporaryDirectory(prefix="gateway-api-update-", dir=CHART.parent) as temp:
            temporary = Path(temp)
            staged_generated = temporary / "generated"
            staged_chart = temporary / "Chart.yaml"
            write_generated(staged_generated, resources)
            staged_chart.write_text(chart_text, encoding="utf-8")
            yaml.safe_load(staged_chart.read_text(encoding="utf-8"))
            install_update(staged_generated, staged_chart)
    except (UpdateError, OSError, UnicodeError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

